import{Ct as e,at as t,it as n,ot as r,st as i,t as a,yt as o}from"./chunks/framework.B_DdUWZ_.js";var s=JSON.parse(`{"title":"@warp-drive/legacy","description":"","frontmatter":{"title":"@warp-drive/legacy","outline":{"level":[2,3]}},"headers":[],"relativePath":"api/@warp-drive/legacy/index.md","filePath":"api/@warp-drive/legacy/index.md"}`),c={name:`api/@warp-drive/legacy/index.md`};function l(a,s,c,l,u,d){let f=e(`ModuleBadge`),p=e(`Badge`);return o(),n(`div`,null,[i(f,{path:`@warp-drive/legacy`}),s[0]||=r(),i(p,{type:`danger`,text:`@legacy`}),s[1]||=t(`<div class="warning custom-block"><p class="custom-block-title">⚠️ <strong>CAUTION</strong></p><p>This package provides support for older <strong><em>Warp</em>Drive</strong> features that have been deprecated and removed from <a href="/pr-preview/pr-11272/api/@warp-drive/core/">@warp-drive/core</a>.</p><p><strong>Projects using these features should refactor away from them with urgency</strong></p></div><p>You&#39;ve probably heard old code patterns referred to as &quot;legacy code&quot; before. In <strong><em>Warp</em>Drive</strong>, Legacy refers to older features to which we are giving a second, extended life. When features are deprecated in <a href="/pr-preview/pr-11272/api/@warp-drive/core/">@warp-drive/core</a>, they are added to <code>@warp-drive/legacy</code> in a way that allows apps to opt-in to bring them back.</p><p>Legacy features will not live forever, but they will receive a second deprecation cycle before being deleted. Notably, <strong>the decision to deprecate a legacy feature does not require an RFC</strong>.</p><p>This low-barrier to removal is because the motivations for deprecating and removing the feature were already enumerated in the original deprecation that removed the feature from core. Generally if code in legacy is being deprecated, it means an event has occurred that requires full removal of support for the feature in order for the project as a whole to continue to advance.</p><p>There is no set schedule to when code in legacy might be deprecated. Sometimes it may become deprecated immediately after the feature is removed from core, other times it may last for several majors. Occasionally a deprecation in core won&#39;t be able to be restored from legacy at all.</p><p>Our policy is to always attempt to provide restoration of a deprecated feature via @warp-drive/legacy, but the decision to provide this long-tail support ultimately depends on how easy a feature is to maintain weighed against the costs to the community and project of keeping it around.</p><h2 id="classes" tabindex="-1">Classes <a class="header-anchor" href="#classes" aria-label="Permalink to “Classes”">​</a></h2><ul><li><a href="./classes/ConfiguredStore">ConfiguredStore</a></li></ul><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><ul><li><a href="./functions/useLegacyStore">useLegacyStore</a></li></ul><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to “Types”">​</a></h2><ul><li><a href="./types/LegacyModelAndNetworkAndRequestStoreSetupOptions">LegacyModelAndNetworkAndRequestStoreSetupOptions</a></li><li><a href="./types/LegacyModelAndNetworkStoreSetupOptions">LegacyModelAndNetworkStoreSetupOptions</a></li><li><a href="./types/LegacyModelStoreSetupOptions">LegacyModelStoreSetupOptions</a></li><li><a href="./types/LegacyStoreSetupOptions">LegacyStoreSetupOptions</a></li></ul>`,12)])}var u=a(c,[[`render`,l]]);export{s as __pageData,u as default};